+int
+main(int argc, char **argv1)
+{
+    TSK_IMG_TYPE_ENUM imgtype = TSK_IMG_TYPE_DETECT;
+    int ch;
+    TSK_TCHAR **argv;
+    unsigned int ssize = 0;
+    TSK_TCHAR *cp;
+    int32_t sec_skew = 0;
+    bool do_hash = false;
+    uint8_t time_mask = TSK_FS_MAC_TYPE_ALL;
+    const char* password = "";
+
